// The typed client generated by sync-engine (`bun run generate` writes
// generated/wire.ts), wrapped so that components never handle the session or
// raw error categories themselves.
import { createHttpClient } from "@mit-sdg/sync-engine-http/client";
import type { BFSThisMessWireHttp } from "../generated/wire.ts";
import { session, signOut } from "./session.ts";

const client = createHttpClient<BFSThisMessWireHttp>({
  baseUrl: new URL("/api", window.location.origin).toString(),
});

// ---------- Endpoint types, derived from the wire so they never drift ----------

type Wire = BFSThisMessWireHttp;
export type Endpoint = keyof Wire extends infer P ? (P extends `/bfsthismess/${infer N}` ? N : never) : never;
type Input<N extends Endpoint> = Wire[`/bfsthismess/${N}`]["input"];
export type Output<N extends Endpoint> = Wire[`/bfsthismess/${N}`]["output"];
// What a component passes: the input without the session, which call() adds.
type Args<N extends Endpoint> = Omit<Input<N>, "session">;

type RoadView = Output<"viewRoad">;
export type Constraints = RoadView["constraints"];
export type PlanRow = RoadView["paths"]["plans"][number];
export type Term = Constraints["startTerm"];
export type Ratings = Output<"viewRatings">["ratings"]["ratings"][number];
export type Schedule = Output<"viewSchedule">["schedule"]["schedule"][number];
export type CourseRow = Output<"searchSubjects">["courses"]["courses"][number];
export type CourseDetails = Output<"viewSubject">["subject"];

// Endpoints anyone may call. Every other endpoint takes the session.
const PUBLIC = new Set<Endpoint>(["register", "logIn", "searchSubjects", "viewSubject", "viewRatings", "viewSchedule"]);

// ---------- Errors ----------

// The HTTP layer only tells the browser the category of a refusal (see
// publicErrors in src/http.ts), not its code or sentence. These tables put back
// the sentence from the design for the refusal each category stands for, per
// endpoint where the same category could mean different things.
type Category = "UNAUTHORIZED" | "NOT_FOUND" | "FORBIDDEN" | "CONFLICT" | "INVALID_REQUEST" | string;

const GENERAL: Record<string, string> = {
  UNAUTHORIZED: "Your session has ended. Please log in again.",
  NOT_FOUND: "There is no such road.",
  FORBIDDEN: "Only the owner can change this road.",
  INVALID_REQUEST: "That request is not valid.",
  INTERNAL_ERROR: "Something went wrong on the server. Please try again.",
  // Transport failures reported by the client itself.
  NETWORK_ERROR: "Could not reach the server. Is the backend running?",
  BAD_STATUS: "The server answered unexpectedly. Is the backend running?",
  BAD_JSON: "The server answered unexpectedly. Is the backend running?",
};

const blockErrors = {
  NOT_FOUND: "There is no such block.",
  INVALID_REQUEST: "A block must require at least one subject.",
};

const BY_ENDPOINT: Partial<Record<Endpoint, Partial<Record<Category, string>>>> = {
  register: { INVALID_REQUEST: "A username and a password are needed.", CONFLICT: "Username is already taken." },
  logIn: { UNAUTHORIZED: "Invalid username or password." },
  newRoad: { INVALID_REQUEST: "A road needs a name, and must start in a Fall or Spring semester." },
  setMajor: { INVALID_REQUEST: "A major cannot be empty." },
  pin: {
    NOT_FOUND: "That subject is not known.",
    CONFLICT: "That semester is locked, or the subject is already prior credit.",
    INVALID_REQUEST: "That semester is outside the road.",
  },
  unPin: { NOT_FOUND: "That subject is not pinned in this road.", CONFLICT: "That semester is locked." },
  setCap: { INVALID_REQUEST: "A cap cannot be negative." },
  addBlock: { INVALID_REQUEST: blockErrors.INVALID_REQUEST },
  setCount: blockErrors,
  addOption: blockErrors,
  removeOption: { ...blockErrors, NOT_FOUND: "That subject is not an option of this block." },
  removeBlock: blockErrors,
};

export class ApiError extends Error {
  constructor(
    readonly endpoint: Endpoint,
    readonly category: Category,
  ) {
    super(BY_ENDPOINT[endpoint]?.[category] ?? GENERAL[category] ?? `Request failed (${category}).`);
  }
}

// ---------- Calls ----------

/**
 * Calls an endpoint, adding the session when the endpoint needs one. Answers
 * the output, or throws an ApiError whose message is the design's sentence.
 * A refused session signs the person out, which returns the app to login.
 */
export async function call<N extends Endpoint>(name: N, args: Args<N>): Promise<Output<N>> {
  const input = PUBLIC.has(name) ? args : { ...args, session: session.value };
  const send = client.bfsthismess[name] as unknown as (input: unknown) => Promise<object>;
  const result = await send(input);
  if ("error" in result) {
    const category = String((result as { error: unknown }).error);
    if (category === "UNAUTHORIZED" && !PUBLIC.has(name)) signOut();
    throw new ApiError(name, category);
  }
  return result as Output<N>;
}

export function message(e: unknown): string {
  return e instanceof Error ? e.message : String(e);
}
